"""Health answers, request ids and the browser security headers (generated by Shikshya, P1b.6 R2)."""
import contextvars
import logging
import re
import uuid

from django.conf import settings
from django.http import JsonResponse

REQUEST_ID = contextvars.ContextVar("request_id", default="-")
_SAFE_ID = re.compile(r"^[A-Za-z0-9._-]{8,64}$")


class RequestIdFilter(logging.Filter):
    """Adds the current request id to every log record (LOGGING names it)."""

    def filter(self, record):
        request = getattr(record, "request", None)
        record.request_id = getattr(request, "request_id", None) or REQUEST_ID.get()
        return True


class HealthCheckMiddleware:
    """/health/ (alive) and /health/ready/ (the database answers), first in the stack: a platform's probe or the
    image's HEALTHCHECK calls them over plain http with a Host of its own, so the host check and the HTTPS redirect
    must not answer them first."""

    def __init__(self, get_response):
        self.get_response = get_response

    def __call__(self, request):
        if request.path == "/health/":
            return JsonResponse({"status": "ok"})
        if request.path == "/health/ready/":
            from django.db import connection
            try:
                connection.ensure_connection()
            except Exception:
                return JsonResponse({"status": "unavailable"}, status=503)
            return JsonResponse({"status": "ready"})
        return self.get_response(request)


class RequestIdMiddleware:
    """One id per request: the proxy's X-Request-ID when it is a plain token, else a new one; sent back."""

    def __init__(self, get_response):
        self.get_response = get_response

    def __call__(self, request):
        incoming = request.headers.get("X-Request-ID", "")
        request_id = incoming if _SAFE_ID.match(incoming) else uuid.uuid4().hex
        request.request_id = request_id
        token = REQUEST_ID.set(request_id)
        try:
            response = self.get_response(request)
        finally:
            REQUEST_ID.reset(token)
        response["X-Request-ID"] = request_id
        return response


class SecurityHeadersMiddleware:
    """settings.CONTENT_SECURITY_POLICY and settings.PERMISSIONS_POLICY on every response that sets neither (added
    outside DEBUG only; the app serves its own pages, so no proxy has to add them)."""

    HEADERS = (("Content-Security-Policy", "CONTENT_SECURITY_POLICY"), ("Permissions-Policy", "PERMISSIONS_POLICY"))

    def __init__(self, get_response):
        self.get_response = get_response

    def __call__(self, request):
        response = self.get_response(request)
        for header, setting in self.HEADERS:
            value = getattr(settings, setting, "")
            if value and header not in response:
                response[header] = value
        return response
